SELECT u.user_id, u.username, u.avatar_url, f.created_at AS followed_at
FROM follows f
JOIN users u ON f.follower_id = u.user_id
WHERE f.followee_id = #{userId}
ORDER BY f.created_at DESC
LIMIT #{limit} OFFSET #{offset}

